# owner: platform
"""Plain-text contact sheet for substitute teachers."""

from typing import Iterable

from rosterkit.models import Student

ROW_FORMAT = "{name:<24} {section:<8} {email}"

# ---
def contact_row(student: Student) -> str:
    """One aligned line. A missing email is an error."""
    if not student.email:
        name = student.display_name
        raise ValueError(f"no email on file for {name}")
    return ROW_FORMAT.format(
        name=student.display_name,
        section=student.section,
        email=student.email
    )

# ---
def contact_sheet(students: Iterable[Student]) -> str:
    """Text rows sorted by name, one per student."""
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    if not ordered:
        raise ValueError("no students to list")
    return "\n".join(map(contact_row, ordered))
